import{H as e,V as t,et as n,j as r}from"./chunks/framework.DSSJFrgb.js";var i=JSON.parse(`{"title":"MySQL 存储引擎","description":"简单记录学习MySQL存储引擎的过程","frontmatter":{"title":"MySQL 存储引擎","date":"2026-08-07T00:00:00.000Z","description":"简单记录学习MySQL存储引擎的过程","tags":["MySQL"]},"headers":[],"relativePath":"tech/mysql/存储引擎.md","filePath":"tech/mysql/存储引擎.md"}`),a={name:`tech/mysql/存储引擎.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e('<h1 id="mysql-存储引擎" tabindex="-1">MySQL 存储引擎 <a class="header-anchor" href="#mysql-存储引擎" aria-label="Permalink to “MySQL 存储引擎”">​</a></h1><h2 id="mysql-体系结构" tabindex="-1">MySQL 体系结构 <a class="header-anchor" href="#mysql-体系结构" aria-label="Permalink to “MySQL 体系结构”">​</a></h2><ul><li>连接层 <ul><li>连接池</li></ul></li><li>服务层 <ul><li>SQL接口，解析器，查询优化器，缓存</li></ul></li><li>引擎层 <ul><li>InnoDB，NDB，MyISAM等存储引擎</li></ul></li><li>存储层 <ul><li>系统文件、文件和日志</li></ul></li></ul><h3 id="连接层" tabindex="-1">连接层 <a class="header-anchor" href="#连接层" aria-label="Permalink to “连接层”">​</a></h3><p>在MySQL体系结构中处于最上层，主要负责与客户端的链接服务，处理权限认证，分配连接池等功能</p><h3 id="服务层" tabindex="-1">服务层 <a class="header-anchor" href="#服务层" aria-label="Permalink to “服务层”">​</a></h3><p>服务层是整个MySQL体系中负责最多功能的一层结构，包括SQL接口，处理SQL语句，优化SQL语句，分析SQL，部分内置函数的执行等</p><h3 id="引擎层" tabindex="-1">引擎层 <a class="header-anchor" href="#引擎层" aria-label="Permalink to “引擎层”">​</a></h3><p>这一层主要负责MySQL与真实物理数据的交互，服务器通过API和存储引擎进行通信</p><h3 id="存储层" tabindex="-1">存储层 <a class="header-anchor" href="#存储层" aria-label="Permalink to “存储层”">​</a></h3><p>存储层很简单直接，就是与操作系统的文件系统打交道，完成存储引擎和系统文件的交互</p><h2 id="存储引擎" tabindex="-1">存储引擎 <a class="header-anchor" href="#存储引擎" aria-label="Permalink to “存储引擎”">​</a></h2><blockquote><p>存储引擎就是存储数据，建立索引，更新\\查询数据等技术的实现方式。存储引擎是基于表的，而不是基于库的。</p></blockquote><div class="language-sql"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">DEFAULT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CHARSET</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">utf8mb4 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">COLLATE=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">utf8mb4_0900_ai_ci</span></span></code></pre></div><p><strong>MySQL 默认的存储引擎就是 InnoDB</strong></p><blockquote><p>查看当前数据库支持哪些存储引擎</p></blockquote><div class="language-sql"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show engines;</span></span></code></pre></div><h2 id="存储引擎特点" tabindex="-1">存储引擎特点 <a class="header-anchor" href="#存储引擎特点" aria-label="Permalink to “存储引擎特点”">​</a></h2><ul><li>InnoDB - 兼顾可靠性和高性能的通用存储引擎，在MySQL5.5之后，InnoDB是默认的MySQL存储引擎 <ul><li>DML遵循ACID模型（一致性、原子性、持久性、隔离性），支持事务</li><li>行级锁</li><li>支持外键</li><li>xxxx.idb （InnoDB引擎的每张表都对应一个这样的表空间文件，存储表结构，数据，索引）</li><li>段页式存储</li></ul></li><li>MyISAM - MySQL早期的默认存储引擎 <ul><li>不支持事务</li><li>不支持外键</li><li>最小支持表锁</li><li>访问速度很快</li><li>xxxx.sdi xxx.MYD xxx.MYI</li></ul></li><li>Memory - 内存存储数据，一般作为临时表 <ul><li>内存存放</li><li>hash索引</li><li>xxx.sdi 存储表结构等信息</li></ul></li></ul>',19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};